import 'package:flutter/material.dart';
import '../main.dart';
import 'comparison_results_screen.dart';
class SavedScreen extends StatelessWidget { const SavedScreen({super.key, required this.controller}); final FavourController controller; @override Widget build(BuildContext context) => ListView(padding: const EdgeInsets.all(20), children: [Text('Saved products', style: Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight: FontWeight.bold)), if (controller.data.favourites.isEmpty) const Padding(padding: EdgeInsets.only(top: 36), child: Center(child: Text('Save a product from its comparison screen.'))), ...controller.data.favourites.map((product) => Card(child: ListTile(title: Text(product.displayName), subtitle: Text(product.packLabel), onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => ComparisonResultsScreen(controller: controller, product: product))), trailing: IconButton(icon: const Icon(Icons.delete_outline), onPressed: () => controller.save(controller.data.copyWith(favourites: controller.data.favourites.where((item) => item.id != product.id).toList())))))]); }
